vector<vector<int>> buildAdjacencyList(int nodeCount,
                                      const vector<pair<int,int>>& edges) {
    vector<vector<int>> adj(nodeCount);
    for (auto [u, v] : edges) {
        adj[u].push_back(v);
        adj[v].push_back(u);   // undirected: write it from both ends
    }
    return adj;
}
